#include <nxt_main.h>
#include <nxt_port_memory_int.h>
#include <assert.h>
#include <stdio.h>

int
main(void)
{
    size_t  n;

    /* size == 0 claims zero chunks, always in range. */
    assert(nxt_port_mmap_chunk_range_valid(0, 0, &n) == 1);
    assert(n == 0);

    /* Exactly one chunk at the boundary size. */
    assert(nxt_port_mmap_chunk_range_valid(0, PORT_MMAP_CHUNK_SIZE, &n) == 1);
    assert(n == 1);

    /* Last valid chunk id, one chunk: in range. */
    assert(nxt_port_mmap_chunk_range_valid(
               PORT_MMAP_CHUNK_COUNT - 1, PORT_MMAP_CHUNK_SIZE, &n) == 1);

    /* chunk_id == COUNT is already out of range on its own. */
    assert(nxt_port_mmap_chunk_range_valid(
               PORT_MMAP_CHUNK_COUNT, PORT_MMAP_CHUNK_SIZE, &n) == 0);

    /* Last valid chunk id, but a size needing 2 chunks: runs past COUNT. */
    assert(nxt_port_mmap_chunk_range_valid(
               PORT_MMAP_CHUNK_COUNT - 1, PORT_MMAP_CHUNK_SIZE * 2, &n) == 0);

    printf("nxt_port_mmap_chunk_range_valid: all cases passed\n");
    return 0;
}
